import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`vs-chat`,hasInputUrl:!1,heroTitle:`More than a chat — AI that does real work`,heroSubtitle:`Perplexity Computer orchestrates 20 AI models — GPT-5.5, Opus 4.8, Gemini 3.1 Pro, and more — to run multi-step workflows for hours. Real browser, real filesystem, sub-agents that solve the toughest problems.`,heroOverlaySteps:[`Analyzing your task and breaking it into steps`,`Selecting the best AI model for each subtask`,`Spinning up specialized agents to execute the work`,`Deliverables assembled — ready for review`],generatingSteps:[`Understanding your task and mapping the steps required`,`Designing an agent to execute each step with the optimal AI model`,`Configuring tool integrations, research pipelines, and output formats`,`Setting up your workflow to deliver finished, actionable results`],featureSectionTitle:`From prompt to finished work`,featureCardTitles:[`Connects to your entire stack`,`Outputs you can ship`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Gmail, Slack, Notion, GitHub, Airtable — Computer plugs into your tools so work flows straight from research to execution.`,`Research reports. Spreadsheets. Code. Drafted emails. Strategy decks. Computer delivers finished work — not conversation fragments you have to reassemble.`],capabilitySectionTitle:`Your AI workforce, on autopilot`,capabilitySectionSubtitle:`Describe the job, step away, come back to finished deliverables.`,capabilityCards:[{title:`Multi-Step Execution`,description:`Computer can break complex projects into dozens of subtasks — researching, analyzing, writing, and building across every step without losing context.`},{title:`Deep Research`,description:`Computer can browse the web, read documents, compare sources, and synthesize findings — delivering cited, structured research instead of pattern-matched guesses.`},{title:`Real-World Actions`,description:`Computer can draft emails, populate spreadsheets, generate reports, and write code — turning AI output into work product you can use immediately.`},{title:`Connect Your Tools`,description:`Computer can read and write across Google Drive, Sheets, Gmail, Slack, Notion, GitHub, and more — build workflows across your entire stack.`},{title:`Memory & Context`,description:`Computer can remember your preferences, past projects, and working style across sessions — so every workflow builds on what it already knows about you.`},{title:`Monitor & Alert`,description:`Computer can run recurring tasks on schedule and alert you when results change — turning one-off projects into always-on workflows.`}]});export{t as default};
